const { randomInt } = require('node:crypto');

/** Generates a six-digit OTP using cryptographically secure randomness. */
function generateCode() {
  return String(randomInt(100000, 1000000));
}

/** Validates settings without logging secrets or contacting Twilio. */
function validateOtpConfig(env = process.env) {
  const mode = (env.OTP_MODE || 'console').trim();
  if (!['console', 'twilio'].includes(mode)) {
    throw new Error('OTP_MODE must be console or twilio.');
  }
  if (mode === 'console') {
    if (env.NODE_ENV === 'production') {
      throw new Error('Console OTP is disabled in production. Configure OTP_MODE=twilio and provider credentials.');
    }
    return { mode };
  }

  const accountSid = (env.TWILIO_ACCOUNT_SID || '').trim();
  const authToken = (env.TWILIO_AUTH_TOKEN || '').trim();
  const from = (env.TWILIO_FROM_NUMBER || '').trim();
  if (!/^AC[0-9a-f]{32}$/i.test(accountSid)) {
    throw new Error('TWILIO_ACCOUNT_SID must be an AC-prefixed 34-character account SID.');
  }
  if (!/^[0-9a-f]{32}$/i.test(authToken)) {
    throw new Error('TWILIO_AUTH_TOKEN must be the 32-character account auth token.');
  }
  if (!/^\+[1-9]\d{7,14}$/.test(from)) {
    throw new Error('TWILIO_FROM_NUMBER must be an approved SMS sender in E.164 format, including + and country code.');
  }
  return { mode, accountSid, authToken, from };
}

/** Sends an OTP to an Indian mobile number; provider acceptance is not delivery confirmation. */
async function sendOtp(mobileNumber, code) {
  if (typeof mobileNumber !== 'string' || !/^\d{10}$/.test(mobileNumber) ||
      typeof code !== 'string' || !/^\d{6}$/.test(code)) {
    throw new Error('OTP delivery requires a 10-digit mobile number and a six-digit code.');
  }
  const config = validateOtpConfig();

  if (config.mode === 'twilio') {
    const twilio = require('twilio');
    try {
      const client = twilio(config.accountSid, config.authToken);
      const message = await client.messages.create({
        body: `Your Akole CCMS OTP is ${code}. Valid for 5 minutes.`,
        from: config.from,
        to: `+91${mobileNumber}`
      });
      if (!message || !message.sid || ![
        'accepted', 'scheduled', 'queued', 'sending', 'sent', 'delivered'
      ].includes(message.status)) {
        throw new Error('Provider did not accept the message.');
      }
      return { accepted: true, mode: 'twilio' };
    } catch (error) {
      // Provider messages can contain recipient details; retain only a numeric diagnostic code.
      const providerCode = Number.isInteger(error.code) ? ` (Twilio code ${error.code})` : '';
      throw new Error(`OTP SMS was not accepted${providerCode}. Check provider credentials, sender permissions, recipient restrictions, and account balance.`);
    }
  }

  console.log(`\n[OTP] Mobile: ${mobileNumber}  Code: ${code}  (dev mode - not actually sent via SMS)\n`);
  return { accepted: false, mode: 'console', devCode: code };
}

module.exports = { generateCode, sendOtp, validateOtpConfig };
